-- Убираем то, чего больше нет в JSON. Строки, на которые ссылаются логи, остаются.
DELETE FROM templates
 WHERE code NOT IN ('W-A', 'W-B', 'W-C', 'W-D', 'W-E', 'W-F', 'W-G', 'T1-NECK', 'T2-SCAP', 'T3-ROW', 'T4-POST', 'T5-PRESS', 'T6-LEGS', 'T7-CORE', 'T8-MOB', 'C1-NECK')
   AND code NOT IN (SELECT template_code FROM sessions);
DELETE FROM exercises
 WHERE code NOT IN ('NK1', 'NK2', 'NK3', 'NK4', 'NK5', 'NK6', 'NK7', 'NK8', 'NK9', 'NK10', 'NK11', 'SC1', 'SC2', 'SC3', 'SC4', 'SC5', 'SC6', 'SC8', 'SC9', 'SC10', 'SC11', 'SC12', 'RW1', 'RW2', 'RW5', 'RW6', 'RW7', 'RW8', 'PC1', 'PC2', 'PC3', 'PC4', 'PC5', 'PC6', 'PC7', 'PC8', 'PC9', 'PR1', 'PR3', 'PR4', 'PR5', 'PR6', 'PR7', 'LG2', 'LG4', 'LG5', 'LG6', 'LG7', 'CR1', 'CR2', 'CR3', 'CR4', 'CR5', 'CR6', 'CR7', 'CR8', 'MB1', 'MB2', 'MB3', 'MB4', 'MB5', 'MB6', 'MB7', 'MB8', 'MB9')
   AND code NOT IN (SELECT exercise_code FROM progression)
   AND code NOT IN (SELECT exercise_code FROM session_sets)
   AND code NOT IN (SELECT exercise_code FROM exercise_media)
   AND code NOT IN (SELECT from_code FROM swaps)
   AND code NOT IN (SELECT to_code FROM swaps);
