INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK1', 'Chin tuck (подбородок назад)', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 0, 'Сядь или встань прямо, взгляд горизонтально вперёд. Не наклоняя головы, отведи её назад — как будто прижимаешь затылок к невидимой стене. Под подбородком появится складка: это и есть правильно. Держи и отпусти плавно.', 'Задирать подбородок вверх или опускать его к груди — голова едет строго назад.', NULL, 1, 'neck_flex', 1, 3, 10, 30, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK2', 'Изометрия сгибания шеи', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 0, 'Сядь прямо, положи ладонь на лоб. Дави лбом в ладонь, а ладонью навстречу — голова при этом не двигается ни на сантиметр. Усилие вполсилы, дыхание ровное. Отпускай плавно, без рывка.', 'Давить в полную силу и задерживать дыхание.', NULL, 1, 'neck_iso', 1, 3, 10, 30, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK3', 'Изометрия разгибания шеи', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 0, 'Сцепи ладони на затылке. Дави затылком назад в ладони, руками — вперёд, голова остаётся на месте. Шея нейтральна: подбородок не задран. Отпускай плавно, без рывка.', 'Запрокидывать голову назад вместо неподвижного упора.', NULL, 1, 'neck_iso', 1, 3, 10, 30, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK4', 'Изометрия вбок', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 1, 'Положи правую ладонь на правый висок. Дави виском в ладонь вбок, ладонью навстречу — голова не сдвигается. Плечо остаётся внизу, к уху не поднимается. Отпусти плавно и повтори в другую сторону.', 'Подъём плеча к уху вместо работы шеи.', NULL, 1, 'neck_iso', 1, 3, 10, 30, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK5', 'Изометрия ротации', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 1, 'Положи правую ладонь на правую скулу. Пытайся повернуть голову вправо, ладонью удерживай — голова стоит на месте. Усилие вполсилы, без рывка. Отпусти плавно и повтори в другую сторону.', NULL, NULL, 1, 'neck_iso', 1, 3, 10, 30, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK6', 'Растяжка верхней трапеции', 'neck', 'stretch', 'none', NULL, NULL, 'seconds', 1, 'Сядь на стул и подложи правую ладонь под правое бедро — так правое плечо останется внизу. Наклони голову левым ухом к левому плечу, лицо смотрит вперёд. Левой рукой возьмись за макушку справа и мягко добавь наклон, без рывка. Тянуть должно по правой стороне шеи от уха к плечу. Держи и поменяй сторону.', 'Тянуть рывком или поворачивать лицо вниз — это уже другое упражнение.', NULL, 1, 'neck_stretch', 1, 2, 10, 45, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK7', 'Растяжка леватора лопатки', 'neck', 'stretch', 'none', NULL, NULL, 'seconds', 1, 'Сядь, правую ладонь подложи под правое бедро. Поверни голову влево примерно на 45 градусов и опусти нос к левой подмышке. Левой рукой мягко дожми затылок вниз. Тянуть должно сзади и сбоку правой стороны шеи. Держи и поменяй сторону.', NULL, NULL, 1, 'neck_stretch', 1, 2, 10, 45, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK8', 'Подъём головы лёжа', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 0, 'Ляг на спину, колени согнуты, стопы на полу. Сначала сделай chin tuck — подбородок назад, шея длинная. Не теряя его, оторви голову от пола на пару сантиметров. Держи, опусти голову и только потом расслабь подбородок.', 'Тянуться вверх подбородком: голова поднимается ровно, лицом в потолок.', NULL, 1, 'neck_flex', 1, 5, 10, 20, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK9', 'Разгибатели лёжа на животе', 'neck', 'isometric', 'none', NULL, NULL, 'seconds', 0, 'Ляг на живот, лоб положи на сжатые кулаки. Приподними голову и кулаки от пола на пару сантиметров, взгляд остаётся в пол. Шея длинная, затылок тянется вперёд, а не вверх. Держи и опусти плавно.', 'Запрокидывать голову назад и смотреть перед собой.', NULL, 1, 'neck_ext', 1, 5, 10, 20, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK10', 'Дыхание 90/90', 'neck', 'isometric', 'wall', NULL, NULL, 'reps', 0, 'Ляг на спину, голени положи на сиденье стула — бёдра и колени под прямым углом. Прижми поясницу к полу так, чтобы ладонь под неё не пролезала. Вдох носом в нижние рёбра и в бока, живот и рёбра расширяются. Выдох ртом дольше вдоха, рёбра идут вниз.', 'Дышать грудью и плечами вместо рёбер.', NULL, 1, 'breathing', 1, 10, 0, 10, 'вдох 4 с, выдох 6 с')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('NK11', 'Подъём и сброс плеч', 'neck', 'mobility', 'none', NULL, NULL, 'reps', 0, 'Сядь или встань прямо, руки свободно опущены. Подними оба плеча к ушам и сожми их. Задержись вверху. На выдохе отпусти плечи вниз одним сбросом, как тяжёлую сумку. Дай плечам повиснуть и расслабиться, и только потом следующий повтор. За рулём — на остановке, руки на коленях.', 'Опускать плечи медленно и с усилием: смысл в том, чтобы трапеция полностью выключилась.', NULL, 1, 'neck_relax', 2, 10, 15, 5, 'плечи вверх и держи 2 с, сброс, 3 с расслабления')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC1', 'Prone Y', 'scap', 'pull', 'none', NULL, NULL, 'reps', 0, 'Ляг на живот, лоб на полу или на свёрнутом полотенце. Вытяни руки вперёд-в стороны буквой Y, большие пальцы смотрят в потолок. Опусти плечи от ушей и подними прямые руки на 10–15 сантиметров. Работает низ лопаток, а не шея. Опускай медленно.', 'Тянуть плечи к ушам и прогибаться поясницей.', NULL, 1, 'scap_raise', 3, 12, 30, 4, '1 с вверх, держи 1 с, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC2', 'Prone T', 'scap', 'pull', 'none', NULL, NULL, 'reps', 0, 'Ляг на живот, лоб на полу. Разведи прямые руки в стороны на уровне плеч буквой T, ладони смотрят вниз. Сведи лопатки и подними руки от пола. Держи секунду в верхней точке и опусти.', 'Прогиб в пояснице вместо работы лопаток.', NULL, 1, 'scap_raise', 3, 12, 30, 4, '1 с вверх, держи 1 с, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC3', 'Prone W', 'scap', 'pull', 'none', NULL, NULL, 'reps', 0, 'Ляг на живот, лоб на полу. Согни локти и прижми их к рёбрам, кисти на уровне головы — получится буква W. Сведи лопатки и оторви локти и кисти от пола. Плечи держи опущенными.', 'Подтягивать плечи к ушам.', NULL, 1, 'scap_raise', 3, 12, 30, 4, '1 с вверх, держи 1 с, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC4', 'Скольжение по стене', 'scap', 'mobility', 'wall', NULL, NULL, 'reps', 0, 'Встань спиной к стене, стопы в 10 сантиметрах от неё. Прижми к стене поясницу, лопатки и затылок. Прижми к стене предплечья и тыльные стороны кистей, локти на уровне плеч. Скользи руками вверх, не отрывая ни одной точки от стены. Медленно вернись вниз.', 'Отрывать предплечья или поясницу от стены ради амплитуды.', NULL, 1, 'scap_control', 3, 12, 30, 5, '2 с вверх, 3 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC5', 'Face pull с резиной', 'scap', 'pull', 'band', NULL, NULL, 'reps', 0, 'Закрепи резину на уровне груди и возьми концы прямым хватом. Тяни к переносице, разводя руки в стороны, локти выше кистей. В конце движения доверни кисти наружу, как будто показываешь бицепс. Возвращай медленно.', 'Тянуть локтями вниз и подключать шею.', NULL, 1, 'scap_raise', 3, 20, 45, 4, '1 с к лицу, держи 1 с, 2 с обратно')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC6', 'Halo с гирей', 'scap', 'mobility', 'kettlebell', NULL, NULL, 'reps', 1, 'Возьми гирю за рога дном вверх и держи у груди. Веди её кругом вокруг головы, близко к затылку. Голова и шея неподвижны, двигаются только руки. Сделай половину повторов в одну сторону, половину в другую.', 'Шея тянется за гирей.', NULL, 1, 'scap_mobility', 3, 8, 30, 4, 'один медленный круг')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC8', 'Вис на турнике', 'scap', 'isometric', 'bar', NULL, NULL, 'seconds', 0, 'Возьмись за турник прямым хватом на ширине плеч и повисни. Сначала повиси полностью расслабленно. Потом опусти плечи вниз от ушей, не сгибая рук, и подержи. Дыши ровно.', NULL, NULL, 1, 'decompression', 3, 1, 60, 45, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC9', 'Пуловер лёжа', 'scap', 'pull', 'kettlebell', NULL, NULL, 'reps', 0, 'Ляг на спину, колени согнуты, стопы на полу. Возьми одну гирю двумя руками и подними прямые руки над грудью. Прижми поясницу к полу и рёбра вниз. Опусти прямые руки за голову до натяжения под мышками и верни обратно. Поясница от пола не отрывается.', 'Уводить руки далеко за голову за счёт прогиба в пояснице.', NULL, 1, 'lat_stretch', 3, 15, 45, 4, '2 с за голову, 2 с обратно')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC10', 'Обратная «муха» в наклоне', 'scap', 'pull', 'kettlebell', NULL, NULL, 'reps', 0, 'Наклонись вперёд примерно на 45 градусов, спина прямая, колени чуть согнуты. Гири висят под плечами, локти слегка согнуты. Разведи руки в стороны до уровня плеч, сводя лопатки. Опускай медленно. Пять килограммов здесь — рабочий вес, гнаться не за чем.', 'Забрасывать вес рывком корпуса.', NULL, 1, 'scap_raise', 3, 15, 45, 4, '1 с вверх, держи 1 с, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC11', 'Шраги с руками вверху', 'scap', 'pull', 'kettlebell', NULL, NULL, 'reps', 0, 'Встань прямо, стопы на ширине таза, по гире в каждой руке. Подними прямые руки вверх и чуть в стороны, буквой Y. Не сгибая локтей, потянись гирями к потолку и подними плечи к ушам. Задержись вверху. Медленно опусти плечи, руки остаются прямыми и вверху.', 'Сгибать локти и прогибаться в пояснице: живот подтянут, рёбра не торчат вперёд.', NULL, 0, 'scap_upward', 3, 12, 45, 4, '1 с вверх, держи 2 с, 1 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('SC12', 'Вынос гири вверх лёжа', 'scap', 'push', 'kettlebell', NULL, NULL, 'reps', 1, 'Ляг на спину, колени согнуты, стопы на полу. Возьми гирю в правую руку и выпрями руку к потолку. Не сгибая локтя, вытолкни гирю ещё выше — лопатка отрывается от пола. Задержись вверху. Медленно верни лопатку на пол, рука остаётся прямой.', 'Сгибать локоть и толкать гирю рукой: движение идёт только от лопатки.', NULL, 1, 'scap_upward', 3, 15, 30, 3, '1 с вверх, держи 1 с, 1 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('RW1', 'Тяга одной рукой в наклоне', 'row', 'pull', 'kettlebell', 'row', 1, 'reps', 1, 'Поставь левую ладонь и левое колено на сиденье стула, правая стопа на полу. Спина параллельна полу и прямая, взгляд в пол. Гиря в правой руке висит прямо под плечом. Тяни локтем назад вдоль тела к карману, лопатка идёт первой. Опускай в полтора раза медленнее, чем поднимаешь.', 'Тянуть рукой и разворачивать корпус вслед за гирей.', NULL, 1, 'horizontal_row', 3, 15, 45, 3, '1 с вверх, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('RW2', 'Тяга двумя гирями («горилла»)', 'row', 'pull', 'kettlebell', 'row', 1, 'reps', 0, 'Поставь две гири на пол на ширине плеч, встань между ними. Наклонись с прямой спиной, таз назад, колени чуть согнуты. Возьми гири и тяни поочерёдно, локоть вдоль тела. Корпус при этом не проворачивается: таз остаётся ровным.', 'Разворачивать корпус вслед за рукой.', NULL, 1, 'horizontal_row', 3, 20, 60, 3, '1 с вверх, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('RW5', 'Тяга лёжа на животе', 'row', 'pull', 'kettlebell', 'row', 1, 'reps', 1, 'Ляг на живот, руки вытянуты вперёд, гири на полу под кистями. Согни локти и подтяни гири к рёбрам, отрывая их от пола. Лопатки сводятся, лоб остаётся у пола. Опускай медленно.', 'Отрывать грудь от пола, превращая тягу в прогиб.', NULL, 1, 'horizontal_row', 3, 15, 45, 3, '1 с вверх, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('RW6', 'Подтягивания', 'row', 'pull', 'bar', 'row', 7, 'reps', 0, 'Возьмись за турник хватом чуть шире плеч. Из виса сначала опусти плечи вниз от ушей. Тяни себя вверх, ведя локти к рёбрам, грудь к перекладине. Опускайся медленно и до конца.', 'Дёргать корпусом и не доходить до полного виса.', NULL, 1, 'vertical_pull', 3, 6, 90, 4, '1 с вверх, 3 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('RW7', 'Тяга под столом (австралийская)', 'row', 'pull', 'wall', 'row', 4, 'reps', 0, 'Ляг под устойчивый стол и возьмись за его край хватом на ширине плеч. Вытяни тело в прямую линию от пяток до головы, пятки на полу. Подтяни грудь к краю стола, локти вдоль тела. Опускайся медленно, тело остаётся ровным.', 'Проваливать таз вниз.', NULL, 1, 'horizontal_row', 3, 12, 60, 3, '1 с вверх, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('RW8', 'Тяга рюкзака в наклоне', 'row', 'pull', 'backpack', 'row', 3, 'reps', 1, 'Загрузи рюкзак книгами и возьми его за лямки. Наклонись с прямой спиной, таз назад, колени чуть согнуты. Тяни рюкзак к животу, локти вдоль тела, лопатки сводятся. Опускай медленно.', 'Округлять поясницу в наклоне.', NULL, 1, 'horizontal_row', 3, 12, 45, 3, '1 с вверх, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PC1', 'Румынская тяга двумя ногами', 'posterior', 'hinge', 'kettlebell', 'hinge', 2, 'reps', 0, 'Встань, стопы на ширине таза, гири перед бёдрами. Уведи таз назад, как будто закрываешь дверь бёдрами, колени почти прямые. Гири скользят вдоль ног вниз, спина прямая. Опускайся, пока тянет под коленями, и вернись вверх за счёт ягодиц.', 'Приседать вместо наклона и округлять поясницу.', NULL, 1, 'hinge_bilateral', 3, 15, 60, 4, '3 с вниз, 1 с вверх')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PC2', 'Румынская тяга на одной ноге', 'posterior', 'hinge', 'kettlebell', 'hinge', 3, 'reps', 1, 'Встань на левую ногу, гиря в правой руке. Наклоняйся вперёд, одновременно уводя правую ногу назад — корпус и нога идут одной линией. Таз держи ровным: правое бедро не заваливается вверх. Опустись до параллели с полом и вернись, толкая пол левой пяткой. Сделай все повторы на одну ногу, потом на другую.', 'Проворачивать таз и тянуться к полу рукой вместо наклона.', NULL, 1, 'hinge_uni', 3, 12, 45, 4, '3 с вниз, 1 с вверх')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PC3', 'Свинг двумя руками', 'posterior', 'hinge', 'kettlebell', NULL, NULL, 'reps', 0, 'Поставь гирю в полуметре перед собой, стопы чуть шире плеч. Наклонись с прямой спиной, зацепи гирю и качни её назад между ног, как мяч в регби. Резко выпрями таз и сожми ягодицы — гиря вылетает вперёд сама, до уровня груди. Руки всё время прямые и расслабленные, они только держат. Дай гире вернуться между ног и повтори.', 'Поднимать гирю руками и приседать вместо удара тазом.', NULL, 1, 'swing', 5, 25, 45, 2, 'один взмах')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PC4', 'Свинг одной рукой', 'posterior', 'hinge', 'kettlebell', 'hinge', 6, 'reps', 1, 'То же движение, что и свинг двумя руками, но гиря в одной руке. Свободная рука идёт вдоль тела для баланса. Плечо рабочей руки не проваливается вперёд, корпус не проворачивается. Сделай половину повторов одной рукой, половину другой.', 'Позволять корпусу проворачиваться вслед за гирей.', NULL, 1, 'swing', 4, 20, 45, 2, 'один взмах')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PC5', 'Good morning с гирей у груди', 'posterior', 'hinge', 'kettlebell', 'hinge', 1, 'reps', 0, 'Прижми гирю к груди двумя руками. Стопы на ширине таза, колени чуть мягкие. Уведи таз назад и наклонись вперёд с прямой спиной до параллели с полом. Вернись вверх, сжимая ягодицы. Это база тазового шарнира: движение идёт из таза, а не из поясницы.', 'Сгибаться в пояснице вместо наклона от таза.', NULL, 1, 'hinge_light', 3, 15, 45, 4, '3 с вниз, 1 с вверх')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PC6', 'Superman', 'posterior', 'hinge', 'none', NULL, NULL, 'reps', 0, 'Ляг на живот, руки вытянуты вперёд. Одновременно оторви от пола руки, грудь и прямые ноги. Взгляд в пол, шея продолжает линию спины. Задержись вверху и опустись.', 'Задирать голову вверх.', NULL, 1, 'back_ext', 3, 12, 45, 5, '1 с вверх, держи 3 с, 1 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PC7', 'Bird dog', 'core', 'isometric', 'none', 'core', 2, 'reps', 1, 'Встань на четвереньки: кисти под плечами, колени под тазом. Вытяни правую руку вперёд и левую ногу назад до одной линии с корпусом. Таз держи ровно, поясница не проваливается. Задержись и поменяй сторону.', 'Заваливать таз набок и поднимать ногу выше спины.', NULL, 1, 'core_stability', 3, 10, 30, 5, 'вытяни, держи 3 с, верни')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PC8', 'Ягодичный мостик на одной ноге', 'posterior', 'hinge', 'none', NULL, NULL, 'reps', 1, 'Ляг на спину, одна стопа на полу, вторая нога выпрямлена или прижата к груди. Толкни пол пяткой опорной ноги и подними таз до линии колено-таз-плечо. Сжимай ягодицу, а не поясницу. Опускайся медленно, не касаясь пола между повторами.', 'Выталкивать таз поясницей и заваливать его набок.', NULL, 1, 'hip_ext', 3, 15, 45, 4, '1 с вверх, держи 2 с, 1 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PC9', 'Становая с рюкзаком', 'posterior', 'hinge', 'backpack', 'hinge', 5, 'reps', 0, 'Поставь загруженный рюкзак между стоп. Уведи таз назад, согни колени, возьми рюкзак за лямки, спина прямая. Встань, выпрямляя ноги и таз одновременно. Опускай тем же путём, не округляя спину.', 'Округлять поясницу на подъёме.', NULL, 1, 'hinge_heavy', 3, 12, 60, 3, '1 с вверх, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PR1', 'Жим стоя одной рукой', 'press', 'push', 'kettlebell', NULL, NULL, 'reps', 1, 'Возьми гирю на плечо: кисть у ключицы, локоть прижат к рёбрам. Сожми ягодицы и пресс, рёбра вниз — корпус как доска. Выжми гирю вверх, в конце рука у уха, ладонь смотрит вперёд. Опускай медленно на плечо. Сделай все повторы одной рукой, потом другой.', 'Отклоняться назад в пояснице вместо жима.', NULL, 0, 'overhead_press', 3, 12, 45, 4, '1 с вверх, 3 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PR3', 'Отжимания', 'press', 'push', 'none', 'push', 4, 'reps', 0, 'Упор лёжа: кисти чуть шире плеч, пальцы вперёд. Тело одной прямой линией от пяток до макушки, ягодицы и пресс напряжены. Опускайся, уводя локти назад под 45 градусов к телу, до касания грудью. Выжми себя обратно, не теряя линии.', 'Проваливать таз и разводить локти в стороны на 90 градусов.', NULL, 1, 'horizontal_press', 3, 15, 60, 4, '3 с вниз, 1 с вверх')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PR4', 'Жим лёжа на полу', 'press', 'push', 'kettlebell', NULL, NULL, 'reps', 0, 'Ляг на спину, колени согнуты, стопы на полу, гири у плеч. Выжми гири вверх до прямых рук, локти под 45 градусов к телу. Опускай до касания локтями пола. Пол сам ограничивает амплитуду — это и делает жим безопасным для плеча.', 'Разводить локти на 90 градусов от тела.', NULL, 1, 'horizontal_press', 3, 20, 45, 3, '1 с вверх, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PR5', 'Внешняя ротация лёжа на боку', 'press', 'pull', 'kettlebell', NULL, NULL, 'reps', 1, 'Ляг на бок, рабочая рука сверху, локоть прижат к рёбрам и согнут под прямым углом. Гиря лежит в кисти у живота. Не отрывая локтя от рёбер, доверни предплечье вверх до потолка. Опускай медленно. Это ротаторы: вес здесь маленький по назначению.', 'Отрывать локоть от корпуса и помогать корпусом.', NULL, 1, 'rotator', 3, 15, 30, 4, '2 с вверх, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PR6', 'Отведение в наклоне (Y-raise стоя)', 'press', 'pull', 'kettlebell', NULL, NULL, 'reps', 0, 'Наклонись вперёд на 45 градусов, спина прямая. Гири висят под плечами, большие пальцы смотрят вверх. Подними прямые руки вперёд-в стороны буквой Y до уровня головы. Плечи держи опущенными, работает низ лопаток.', 'Тянуть плечи к ушам.', NULL, 1, 'scap_raise', 3, 15, 45, 4, '1 с вверх, держи 1 с, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('PR7', 'Подъём гири в сторону', 'press', 'pull', 'kettlebell', NULL, NULL, 'reps', 1, 'Встань прямо, гиря в правой руке у бедра, левой держись за стол или стену. Чуть согни локоть и не меняй этот угол до конца подхода. Подними руку в сторону и немного вперёд, до уровня плеча. Плечо уходит в сторону, а не к уху. Опускай медленно, не роняя гирю.', 'Раскачиваться корпусом и поднимать руку выше плеча.', NULL, 1, 'shoulder_abduction', 3, 12, 45, 4, '1 с вверх, 3 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('LG2', 'Выпад назад', 'legs', 'squat', 'none', 'squat', 4, 'reps', 1, 'Встань прямо, руки перед грудью. Сделай широкий шаг назад и опустись, пока переднее бедро не станет параллельно полу. Колено задней ноги идёт к полу, но не бьётся об него. Вернись, толкая пол передней пяткой. Чередуй ноги.', 'Заваливать переднее колено внутрь.', NULL, 1, 'lunge', 3, 12, 45, 4, '3 с вниз, 1 с вверх')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('LG4', 'Болгарский присед', 'legs', 'squat', 'none', 'squat', 5, 'reps', 1, 'Поставь заднюю стопу на сиденье стула, передняя нога в шаге от него. Опускайся вниз строго вертикально, корпус чуть наклонён вперёд. Переднее колено идёт над стопой, не заваливается внутрь. Вернись, толкая пол передней пяткой. Сделай все повторы на одну ногу, потом на другую.', 'Отталкиваться задней ногой вместо работы передней.', NULL, 1, 'lunge', 3, 12, 60, 4, '3 с вниз, 1 с вверх')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('LG5', 'Присед с весом тела', 'legs', 'squat', 'none', 'squat', 1, 'reps', 0, 'Стопы на ширине плеч, носки чуть наружу. Уведи таз назад и вниз, колени идут в стороны над стопами. Спина прямая, пятки не отрываются от пола, руки вперёд для баланса. Опустись до параллели бедра с полом и встань, толкая пол пятками.', 'Отрывать пятки и сводить колени внутрь.', NULL, 1, 'squat', 3, 25, 45, 3, '2 с вниз, 1 с вверх')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('LG6', 'Присед на одной ноге к стулу', 'legs', 'squat', 'none', 'squat', 7, 'reps', 1, 'Встань перед стулом на одной ноге, вторая вытянута вперёд. Медленно опускайся, уводя таз назад, до касания стула. Не садись весом: коснулся и сразу встал. Руки вперёд для противовеса. Сделай все повторы на одну ногу, потом на другую.', 'Падать на стул и вставать с раскачки.', NULL, 1, 'squat', 3, 8, 60, 5, '4 с вниз, 1 с вверх')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('LG7', 'Подъём на носки на одной ноге', 'legs', 'squat', 'none', NULL, NULL, 'reps', 1, 'Встань на одну ногу, пальцами держись за стену для баланса. Поднимись на носок как можно выше и задержись на секунду. Опускайся медленно на три счёта. Сделай все повторы на одну ногу, потом на другую.', 'Опускаться рывком.', NULL, 1, 'calf', 3, 20, 30, 4, '1 с вверх, держи 1 с, 2 с вниз')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('CR1', 'Планка', 'core', 'isometric', 'none', 'core', 3, 'seconds', 0, 'Упор на предплечья: локти строго под плечами, предплечья параллельны. Вытяни тело в прямую линию от пяток до макушки. Подверни таз под себя и сожми ягодицы — поясница не проваливается. Взгляд в пол, шея продолжает линию спины. Дыши ровно всё время удержания.', 'Проваливать таз и задирать его вверх домиком.', NULL, 1, 'core_iso', 3, 1, 45, 60, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('CR2', 'Боковая планка', 'core', 'isometric', 'none', 'core', 5, 'seconds', 1, 'Ляг на бок, локоть строго под плечом, ноги вытянуты одна на другой. Подними таз до прямой линии от стоп до головы. Верхнее плечо строго над нижним, корпус не заваливается вперёд. Держи и поменяй сторону.', 'Проваливать таз вниз и разворачивать корпус к полу.', NULL, 1, 'core_iso', 3, 1, 30, 45, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('CR3', 'Чемоданная переноска', 'core', 'carry', 'kettlebell', NULL, NULL, 'steps', 1, 'Возьми гирю в одну руку, как чемодан, вторая рука свободна. Встань прямо: плечи на одном уровне, гиря не тянет корпус набок. Иди ровным шагом, не наклоняясь. Пройди половину шагов с гирей в одной руке, половину — в другой.', 'Заваливаться в сторону гири или наклоняться от неё.', NULL, 1, 'carry', 3, 60, 45, 1, 'шаг в секунду')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('CR4', 'Фермерская переноска', 'core', 'carry', 'kettlebell', NULL, NULL, 'steps', 0, 'Возьми по гире в каждую руку и встань прямо. Плечи опущены и раскрыты, рёбра вниз, взгляд вперёд. Иди ровным шагом, дыши. Хват отпускает первым — это нормально.', 'Сутулиться под весом.', NULL, 1, 'carry', 3, 80, 60, 1, 'шаг в секунду')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('CR5', 'Turkish get-up', 'core', 'complex', 'kettlebell', NULL, NULL, 'reps', 1, 'Ляг на спину, гиря в правой руке, рука выпрямлена в потолок. Правое колено согнуто, стопа на полу, левая рука и нога в стороны под 45 градусов. Перекатись на левое предплечье, потом на левую ладонь, глядя на гирю. Подними таз и протяни левую ногу назад в положение выпада. Встань и разбери движение обратно тем же порядком. Первые недели делай без веса.', 'Спешить и терять гирю из поля зрения.', NULL, 0, 'complex', 3, 2, 60, 40, 'один медленный подъём и спуск')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('CR6', 'Dead bug', 'core', 'isometric', 'none', 'core', 1, 'reps', 1, 'Ляг на спину, руки в потолок, бёдра и колени под прямым углом. Прижми поясницу к полу и не отпускай её всё упражнение. Опусти правую руку за голову и левую ногу к полу одновременно. Вернись и повтори с другой парой. Как только поясница отрывается — амплитуда закончилась.', 'Отрывать поясницу от пола ради длинного движения.', NULL, 1, 'core_stability', 3, 12, 30, 4, '2 с опускаешь, 2 с возвращаешь')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('CR7', 'Rack carry', 'core', 'carry', 'kettlebell', NULL, NULL, 'steps', 1, 'Возьми гири на плечи: кисти у ключиц, локти прижаты к рёбрам. Встань прямо, рёбра вниз, ягодицы напряжены. Иди ровным шагом, дыша животом. Это переноска, а не жим: гири остаются на плечах.', 'Отклоняться назад в пояснице.', NULL, 1, 'carry', 3, 60, 45, 1, 'шаг в секунду')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('CR8', 'Переноска рюкзака с правильной посадкой', 'core', 'carry', 'backpack', NULL, NULL, 'steps', 0, 'Надень рюкзак и затяни лямки так, чтобы он сидел высоко на спине. Расправь плечи, рёбра вниз, взгляд вперёд. Иди ровным шагом, не наклоняясь вперёд под весом. Если тянет вперёд — рюкзак тяжёлый или сидит низко.', 'Носить рюкзак низко на пояснице и сутулиться.', NULL, 1, 'carry', 3, 80, 60, 1, 'шаг в секунду')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('MB1', 'Разгибание грудного отдела на полотенце', 'mobility', 'mobility', 'none', NULL, NULL, 'reps', 0, 'Сверни полотенце в плотный валик толщиной с предплечье и положи на пол. Ляг на него спиной поперёк, валик под лопатками, колени согнуты, стопы на полу. Сцепи ладони на затылке и поддержи голову. Мягко прогнись назад через валик, раскрывая грудной отдел, и вернись. Поясница прижата к полу и в движении не участвует.', 'Прогибаться поясницей вместо грудного отдела.', NULL, 1, 't_spine', 2, 12, 15, 5, '2 с прогиб, держи 1 с, 2 с обратно')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('MB2', 'Open book', 'mobility', 'mobility', 'none', NULL, NULL, 'reps', 1, 'Ляг на левый бок, колени согнуты под прямым углом, руки вытянуты вперёд одна на другой. Не двигая коленями, разверни правую руку и грудь назад к полу. Взгляд следует за рукой. Задержись в раскрытии и вернись. Сделай все повторы на одну сторону, потом на другую.', 'Отрывать колени от пола, подменяя грудной отдел поясницей.', NULL, 1, 't_spine', 2, 10, 15, 6, '2 с раскрытие, держи 2 с, 2 с обратно')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('MB3', 'Cat-cow', 'mobility', 'mobility', 'none', NULL, NULL, 'reps', 0, 'Встань на четвереньки: кисти под плечами, колени под тазом. На выдохе округли спину вверх и опусти голову — это кошка. На вдохе прогнись, раскрывая грудь, и подними взгляд — это корова. Двигайся медленно, включая шею в обе фазы.', NULL, NULL, 1, 'spine_flow', 2, 12, 15, 6, '3 с кошка, 3 с корова')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('MB4', 'Растяжка груди в дверном проёме', 'mobility', 'stretch', 'wall', NULL, NULL, 'seconds', 1, 'Встань в дверном проёме, поставь предплечье на косяк, локоть на уровне плеча. Сделай небольшой шаг вперёд той же ногой, корпус разворачивается от руки. Тянуть должно по передней поверхности плеча и груди. Держи и поменяй сторону.', 'Выгибать поясницу вместо раскрытия груди.', NULL, 1, 'pec_stretch', 1, 2, 10, 45, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('MB5', 'World''s greatest stretch', 'mobility', 'mobility', 'none', NULL, NULL, 'reps', 1, 'Сделай широкий выпад вперёд правой ногой, обе ладони на полу у стопы. Опусти правый локоть к полу внутри стопы и подержи пару секунд. Потом поставь правую ладонь на пол и раскрой корпус, уводя правую руку в потолок. Взгляд за рукой. Вернись и поменяй сторону.', NULL, NULL, 1, 'hip_mobility', 2, 6, 15, 10, 'медленно, с паузой в каждой позиции')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('MB6', 'Thread the needle', 'mobility', 'mobility', 'none', NULL, NULL, 'seconds', 1, 'Встань на четвереньки: кисти под плечами, колени под тазом. Продень правую руку под корпусом влево до упора, опуская правое плечо и висок на пол. Таз держи на месте, над коленями. Держи и поменяй сторону.', NULL, NULL, 1, 't_spine', 1, 2, 10, 30, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('MB7', 'Растяжка сгибателей бедра', 'mobility', 'stretch', 'none', NULL, NULL, 'seconds', 1, 'Встань в выпад, заднее колено на полу, под него подложи что-нибудь мягкое. Подверни таз под себя, как будто прячешь копчик — поясница выпрямляется. Сохраняя подворот, чуть подай таз вперёд. Тянуть должно спереди бедра задней ноги. Держи и поменяй сторону.', 'Уходить тазом вперёд без подворота — тогда тянет поясницу, а не бедро.', NULL, 1, 'hip_mobility', 1, 2, 10, 45, NULL)
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('MB8', 'Растяжка голеностопа у стены', 'mobility', 'stretch', 'wall', NULL, NULL, 'seconds', 1, 'Встань лицом к стене, поставь стопу в 10 сантиметрах от неё. Толкай колено вперёд к стене, пятка остаётся на полу. Если колено легко достаёт — отодвинь стопу дальше. Сделай все повторы и поменяй ногу.', 'Отрывать пятку от пола.', NULL, 1, 'ankle', 2, 15, 15, 3, '2 с к стене, 1 с обратно')
INSERT INTO exercises (code, name, group_code, pattern, equipment, chain, chain_level, unit, unilateral, cues, mistakes, video_url, neck_safe, swap_group, dose_sets, dose_reps, dose_rest_sec, rep_sec, rep_note) VALUES ('MB9', 'Прогулка без рюкзака', 'mobility', 'mobility', 'none', NULL, NULL, 'seconds', 0, 'Иди в спокойном темпе, руки свободны. Плечи опущены и раскрыты, взгляд вперёд, а не в телефон. Плечи не держат вес — в этом весь смысл.', NULL, NULL, 1, 'walk', 1, 1, 0, 1800, NULL)
